export default JSON.parse("{\"schema\":\"universal.covenant-alignment-runtime.v8\",\"axes\":{\"altruism\":{\"id\":\"altruism\",\"name\":\"Altruism\",\"low\":\"Selfish\",\"neutral\":\"Balanced\",\"high\":\"Altruistic\",\"profile_axis\":true,\"question\":\"Whose welfare receives priority when interests conflict?\",\"low_signals\":[\"personal gain before others\",\"treating lives as expendable\",\"exploitation\",\"protecting advantage over people\"],\"high_signals\":[\"sacrifice\",\"compassion\",\"generosity\",\"accepting meaningful cost to protect others\"],\"not_confused_with\":[\"politeness\",\"lawfulness\",\"cooperation\",\"public reputation\"]},\"lawfulness\":{\"id\":\"lawfulness\",\"name\":\"Lawfulness\",\"low\":\"Chaotic\",\"neutral\":\"Independent\",\"high\":\"Lawful\",\"profile_axis\":true,\"question\":\"How does the character relate to laws, institutions, hierarchy, and stable procedure?\",\"low_signals\":[\"rebellion\",\"personal freedom over imposed structure\",\"breaking procedure\",\"rejecting institutional authority\"],\"high_signals\":[\"duty\",\"stable procedure\",\"legitimate hierarchy\",\"treaties and institutional responsibility\"],\"not_confused_with\":[\"goodness\",\"honesty\",\"obedience to every ruler\",\"lack of creativity\"]},\"cooperation\":{\"id\":\"cooperation\",\"name\":\"Cooperation\",\"low\":\"Combative\",\"neutral\":\"Independent\",\"high\":\"Cooperative\",\"profile_axis\":true,\"question\":\"Does the character solve conflict through opposition and dominance or through coordination and shared authority?\",\"low_signals\":[\"escalation\",\"dominance\",\"competition\",\"refusing compromise\"],\"high_signals\":[\"coordination\",\"de-escalation\",\"shared authority\",\"teamwork and consensus\"],\"not_confused_with\":[\"altruism\",\"loyalty\",\"sociability\",\"working alone\"]},\"honor\":{\"id\":\"honor\",\"name\":\"Honor\",\"low\":\"Dishonorable\",\"neutral\":\"Situational\",\"high\":\"Honorable\",\"profile_axis\":true,\"question\":\"How reliably does the character treat trust, truth, vows, surrender, and accountability?\",\"low_signals\":[\"betrayal\",\"deception for advantage\",\"oathbreaking\",\"abusing surrender or trust\"],\"high_signals\":[\"integrity\",\"truthful dealing\",\"kept commitments\",\"restraint and accountability\"],\"not_confused_with\":[\"lawfulness\",\"mercy\",\"idealism\",\"pragmatism\"]},\"mercy\":{\"id\":\"mercy\",\"name\":\"Mercy\",\"low\":\"Ruthless\",\"neutral\":\"Tempered\",\"high\":\"Merciful\",\"profile_axis\":false,\"question\":\"How does the character treat defeated, guilty, helpless, or dangerous beings when they possess power over them?\",\"low_signals\":[\"elimination as the default\",\"collective punishment\",\"using suffering as leverage\",\"denying surrender\"],\"high_signals\":[\"proportionate force\",\"accepting surrender\",\"restoration\",\"distinguishing threat from person\"],\"not_confused_with\":[\"altruism\",\"weakness\",\"pacifism\",\"forgiveness without boundaries\"]},\"transformation\":{\"id\":\"transformation\",\"name\":\"Transformation\",\"low\":\"Preservative\",\"neutral\":\"Adaptive\",\"high\":\"Transformative\",\"profile_axis\":false,\"question\":\"Does the character preserve existing forms and continuity, or embrace alteration, reinvention, and becoming?\",\"low_signals\":[\"continuity\",\"tradition\",\"restoration of established forms\",\"protecting stable systems\"],\"high_signals\":[\"adaptation\",\"reinvention\",\"mutation or reform\",\"accepting irreversible change\"],\"not_confused_with\":[\"lawfulness\",\"progress\",\"goodness\",\"chaos\"]},\"autonomy\":{\"id\":\"autonomy\",\"name\":\"Autonomy\",\"low\":\"Duty-Bound\",\"neutral\":\"Balanced\",\"high\":\"Self-Directed\",\"profile_axis\":false,\"question\":\"Does the character ground decisions in external duties and claims, or in self-authored conviction and consent?\",\"low_signals\":[\"service\",\"vows and inherited duty\",\"obedience to chosen obligations\",\"collective identity\"],\"high_signals\":[\"personal conscience\",\"self-authored identity\",\"consent\",\"refusal of imposed ownership\"],\"not_confused_with\":[\"selfishness\",\"lawlessness\",\"disloyalty\",\"isolation\"]},\"restraint\":{\"id\":\"restraint\",\"name\":\"Restraint\",\"low\":\"Unrestrained\",\"neutral\":\"Measured\",\"high\":\"Disciplined\",\"profile_axis\":false,\"question\":\"How strongly does the character regulate appetite, anger, fear, ambition, power, and impulse?\",\"low_signals\":[\"indulgence\",\"impulsive escalation\",\"power without limits\",\"surrender to appetite\"],\"high_signals\":[\"discipline\",\"proportion\",\"delayed gratification\",\"controlled use of power\"],\"not_confused_with\":[\"emotionlessness\",\"lawfulness\",\"timidity\",\"lack of passion\"]}},\"phases\":[{\"phase\":1,\"name\":\"Defining Low\",\"range\":\"0-749\",\"meaning\":\"The low endpoint is an established part of identity and repeatedly appears under pressure.\",\"steps\":[\"0-249 Absolute Low\",\"250-499 Deep Low\",\"500-749 Established Low\"]},{\"phase\":2,\"name\":\"Contested Low\",\"range\":\"750-1499\",\"meaning\":\"The character leans low, but exceptions and internal conflict remain common.\",\"steps\":[\"750-999 Low-Leaning\",\"1000-1249 Contested Low\",\"1250-1499 Edge Low\"]},{\"phase\":0,\"name\":\"Pivot\",\"range\":\"1500\",\"meaning\":\"No demonstrated directional commitment. This is a precise center, not a personality absence.\",\"steps\":[\"1500 Exact Pivot\"]},{\"phase\":3,\"name\":\"Contested High\",\"range\":\"1501-2249\",\"meaning\":\"The character leans high, but the commitment is still tested, situational, or developing.\",\"steps\":[\"1501-1749 Edge High\",\"1750-1999 Contested High\",\"2000-2249 High-Leaning\"]},{\"phase\":4,\"name\":\"Defining High\",\"range\":\"2250-3000\",\"meaning\":\"The high endpoint is an established part of identity and repeatedly survives serious pressure.\",\"steps\":[\"2250-2499 Established High\",\"2500-2749 Deep High\",\"2750-3000 Absolute High\"]}],\"profiles\":{\"lawful_renegade\":{\"name\":\"Lawful Renegade\",\"profile\":\"Selfish \u2014 Lawful \u2014 Cooperative \u2014 Dishonorable\",\"description\":\"A rebel in legal robes. They exploit loopholes, misrepresent motives, and use cooperative institutions for personal gain. Their planning may be pragmatic, but their low Honor comes from manipulating trust and abandoning principles when useful.\"},\"lawful_drifter\":{\"name\":\"Lawful Drifter\",\"profile\":\"Selfish \u2014 Lawful \u2014 Cooperative \u2014 Neutral\",\"description\":\"Follows the rules just enough to survive. Doesn't stick around long, but won't burn bridges either. A ghost with a code.\"},\"lawful_champion\":{\"name\":\"Lawful Champion\",\"profile\":\"Selfish \u2014 Lawful \u2014 Cooperative \u2014 Honorable\",\"description\":\"Seeks glory under the banner of law. Noble in words, loyal to allies \u2014 yet always with an eye on personal legacy.\"},\"lawful_strategist\":{\"name\":\"Lawful Strategist\",\"profile\":\"Selfish \u2014 Lawful \u2014 Neutral \u2014 Dishonorable\",\"description\":\"A long-game planner who treats rules, promises, and people as pieces. They are disciplined and effective, but will deceive, sacrifice allies, or reinterpret obligations to secure their own advantage.\"},\"lawful_knave\":{\"name\":\"Lawful Knave\",\"profile\":\"Selfish \u2014 Lawful \u2014 Neutral \u2014 Neutral\",\"description\":\"Keeps just enough law to stay out of jail. A slippery operator who toes the line without any deeper loyalties.\"},\"lawful_avenger\":{\"name\":\"Lawful Avenger\",\"profile\":\"Selfish \u2014 Lawful \u2014 Neutral \u2014 Honorable\",\"description\":\"Enforces personal justice like a holy wrathblade. Rules are tools, not ideals \u2014 they punish to feed their pride.\"},\"lawful_mercenary\":{\"name\":\"Lawful Mercenary\",\"profile\":\"Selfish \u2014 Lawful \u2014 Combative \u2014 Dishonorable\",\"description\":\"A sword for hire who respects the structure of a contract only while it benefits them. Precise and professional, yet willing to exploit clauses, conceal risks, or betray the spirit of an agreement.\"},\"lawful_marauder\":{\"name\":\"Lawful Marauder\",\"profile\":\"Selfish \u2014 Lawful \u2014 Combative \u2014 Neutral\",\"description\":\"Wears structure like armor while carving a bloody path. Not cruel \u2014 just committed to their own violent climb.\"},\"lawful_gladiator\":{\"name\":\"Lawful Gladiator\",\"profile\":\"Selfish \u2014 Lawful \u2014 Combative \u2014 Honorable\",\"description\":\"Upholds combat as ceremony. Respects tradition and fair fights \u2014 but glory and personal honor always come first.\"},\"neutral_renegade\":{\"name\":\"Neutral Renegade\",\"profile\":\"Selfish \u2014 Neutral \u2014 Cooperative \u2014 Dishonorable\",\"description\":\"Works with others when useful, then withholds truth or deserts commitments when the cost rises. Smart and efficient, but tolerated rather than trusted.\"},\"neutral_drifter\":{\"name\":\"Neutral Drifter\",\"profile\":\"Selfish \u2014 Neutral \u2014 Cooperative \u2014 Neutral\",\"description\":\"A wanderer with just enough charm to stay welcome. Avoids attachment but doesn't actively sabotage it.\"},\"neutral_champion\":{\"name\":\"Neutral Champion\",\"profile\":\"Selfish \u2014 Neutral \u2014 Cooperative \u2014 Honorable\",\"description\":\"Fights for group causes \u2014 until the applause fades. Their heroism is real... but so is their thirst for praise.\"},\"neutral_strategist\":{\"name\":\"Neutral Strategist\",\"profile\":\"Selfish \u2014 Neutral \u2014 Neutral \u2014 Dishonorable\",\"description\":\"Judges everything by personal outcome. Plans quietly, manipulates information, and treats ethical limits as obstacles rather than commitments.\"},\"neutral_knave\":{\"name\":\"Neutral Knave\",\"profile\":\"Selfish \u2014 Neutral \u2014 Neutral \u2014 Neutral\",\"description\":\"A wildcard with no compass. Acts on impulse or opportunity \u2014 sometimes helpful, often a headache.\"},\"neutral_avenger\":{\"name\":\"Neutral Avenger\",\"profile\":\"Selfish \u2014 Neutral \u2014 Neutral \u2014 Honorable\",\"description\":\"Revenge is their religion. Morality isn\u2019t the goal \u2014 just evening the score, no matter who gets in the way.\"},\"neutral_mercenary\":{\"name\":\"Neutral Mercenary\",\"profile\":\"Selfish \u2014 Neutral \u2014 Combative \u2014 Dishonorable\",\"description\":\"Coin, leverage, and survival come first. They may honor a deal when convenient, but will switch sides, hide terms, or exploit weakness if the reward is better.\"},\"neutral_marauder\":{\"name\":\"Neutral Marauder\",\"profile\":\"Selfish \u2014 Neutral \u2014 Combative \u2014 Neutral\",\"description\":\"Fights not for principle, but power. They don\u2019t pick sides \u2014 only targets.\"},\"neutral_gladiator\":{\"name\":\"Neutral Gladiator\",\"profile\":\"Selfish \u2014 Neutral \u2014 Combative \u2014 Honorable\",\"description\":\"Honors the duel, not the war. Cares deeply about reputation and performance, not cause or creed.\"},\"chaotic_renegade\":{\"name\":\"Chaotic Renegade\",\"profile\":\"Selfish \u2014 Chaotic \u2014 Cooperative \u2014 Dishonorable\",\"description\":\"A team-friendly anarchist until loyalty becomes inconvenient. They improvise brilliantly but lie, manipulate, or abandon allies without accepting the consequences.\"},\"chaotic_drifter\":{\"name\":\"Chaotic Drifter\",\"profile\":\"Selfish \u2014 Chaotic \u2014 Cooperative \u2014 Neutral\",\"description\":\"A storm with a smile. Allies when it\u2019s fun, disappears when it\u2019s not. Hard to hate \u2014 but harder to trust.\"},\"chaotic_champion\":{\"name\":\"Chaotic Champion\",\"profile\":\"Selfish \u2014 Chaotic \u2014 Cooperative \u2014 Honorable\",\"description\":\"A rebel hero \u2014 dramatic, bold, magnetic. Loyal in the moment, but always the star of their own tale.\"},\"chaotic_strategist\":{\"name\":\"Chaotic Strategist\",\"profile\":\"Selfish \u2014 Chaotic \u2014 Neutral \u2014 Dishonorable\",\"description\":\"An unpredictable mastermind who plays every side. The dishonor lies not in improvisation, but in broken trust, concealed motives, and deliberate betrayal.\"},\"chaotic_knave\":{\"name\":\"Chaotic Knave\",\"profile\":\"Selfish \u2014 Chaotic \u2014 Neutral \u2014 Neutral\",\"description\":\"Pure mischief incarnate. Chaos is its own reward \u2014 no loyalty, no plan, just vibes.\"},\"chaotic_avenger\":{\"name\":\"Chaotic Avenger\",\"profile\":\"Selfish \u2014 Chaotic \u2014 Neutral \u2014 Honorable\",\"description\":\"Burns worlds to avenge one wound. Justice isn\u2019t blind \u2014 it\u2019s furious.\"},\"chaotic_mercenary\":{\"name\":\"Chaotic Mercenary\",\"profile\":\"Selfish \u2014 Chaotic \u2014 Combative \u2014 Dishonorable\",\"description\":\"A volatile warrior for hire who treats promises as temporary. They may change sides mid-fight for better pay, greater thrill, or personal advantage.\"},\"chaotic_marauder\":{\"name\":\"Chaotic Marauder\",\"profile\":\"Selfish \u2014 Chaotic \u2014 Combative \u2014 Neutral\",\"description\":\"Wrecks, raids, and rages with zero remorse. No ideology \u2014 just destruction.\"},\"chaotic_gladiator\":{\"name\":\"Chaotic Gladiator\",\"profile\":\"Selfish \u2014 Chaotic \u2014 Combative \u2014 Honorable\",\"description\":\"Fights like it\u2019s performance art. Theatrics, blood, and brutal showdowns define them.\"},\"lawful_operator\":{\"name\":\"Lawful Operator\",\"profile\":\"Neutral \u2014 Lawful \u2014 Cooperative \u2014 Dishonorable\",\"description\":\"Works effectively inside institutions and teams, but manipulates procedure, hides costs, or uses allies as tools. Their public reliability masks a willingness to exploit trust. [Completed combination added in this merged edition.]\"},\"lawful_collaborator\":{\"name\":\"Lawful Collaborator\",\"profile\":\"Neutral \u2014 Lawful \u2014 Cooperative \u2014 Neutral\",\"description\":\"A dependable participant in structured groups. They value order and teamwork, but are neither consistently self-sacrificing nor guided by a firm personal code. [Completed combination added in this merged edition.]\"},\"lawful_harmonizer\":{\"name\":\"Lawful Harmonizer\",\"profile\":\"Neutral \u2014 Lawful \u2014 Cooperative \u2014 Honorable\",\"description\":\"Builds stable institutions, resolves conflict fairly, and keeps commitments even when compromise is difficult. Order and cooperation matter more than personal glory. [Completed combination added in this merged edition.]\"},\"lawful_adapter\":{\"name\":\"Lawful Adapter\",\"profile\":\"Neutral \u2014 Lawful \u2014 Neutral \u2014 Dishonorable\",\"description\":\"Uses rules and hierarchy as survival tools, changing loyalties or interpretations whenever advantage demands it. They respect structure more than they respect trust. [Completed combination added in this merged edition.]\"},\"lawful_moderate\":{\"name\":\"Lawful Moderate\",\"profile\":\"Neutral \u2014 Lawful \u2014 Neutral \u2014 Neutral\",\"description\":\"Prefers order, proportion, and predictable procedure without strong altruistic or selfish pressure. Their personal code is situational rather than deeply fixed. [Completed combination added in this merged edition.]\"},\"lawful_ethicist\":{\"name\":\"Lawful Ethicist\",\"profile\":\"Neutral \u2014 Lawful \u2014 Neutral \u2014 Honorable\",\"description\":\"Supports structure while judging each duty against a consistent inner code. They are neither especially selfless nor selfish, but they are principled and accountable. [Completed combination added in this merged edition.]\"},\"lawful_ravager\":{\"name\":\"Lawful Ravager\",\"profile\":\"Neutral \u2014 Lawful \u2014 Combative \u2014 Dishonorable\",\"description\":\"Uses sanctioned force aggressively and treats legal authority as permission to intimidate, exploit surrender, or conceal misconduct. [Completed combination added in this merged edition.]\"},\"lawful_scoundrel\":{\"name\":\"Lawful Scoundrel\",\"profile\":\"Neutral \u2014 Lawful \u2014 Combative \u2014 Neutral\",\"description\":\"A disciplined bruiser who accepts hierarchy and conflict but follows no dependable moral code beyond the rules currently in force. [Completed combination added in this merged edition.]\"},\"lawful_warrior\":{\"name\":\"Lawful Warrior\",\"profile\":\"Neutral \u2014 Lawful \u2014 Combative \u2014 Honorable\",\"description\":\"Fights under rules of engagement, accepts consequences, and keeps their word. They may be confrontational, but their conduct remains principled. [Completed combination added in this merged edition.]\"},\"neutral_operator\":{\"name\":\"Neutral Operator\",\"profile\":\"Neutral \u2014 Neutral \u2014 Cooperative \u2014 Dishonorable\",\"description\":\"A practical team player who gets results, but may hide costs, mislead partners, or discard commitments when efficiency demands it. Pragmatism alone is not dishonor; exploiting trust is.\"},\"neutral_collaborator\":{\"name\":\"Neutral Collaborator\",\"profile\":\"Neutral \u2014 Neutral \u2014 Cooperative \u2014 Neutral\",\"description\":\"Goes with the flow. A team member who supports without leading or resisting \u2014 blends in, stabilizes chaos.\"},\"neutral_harmonizer\":{\"name\":\"Neutral Harmonizer\",\"profile\":\"Neutral \u2014 Neutral \u2014 Cooperative \u2014 Honorable\",\"description\":\"Balances relationships with grace. A quiet peacemaker, not for recognition, but because harmony matters.\"},\"neutral_adapter\":{\"name\":\"Neutral Adapter\",\"profile\":\"Neutral \u2014 Neutral \u2014 Neutral \u2014 Dishonorable\",\"description\":\"A survivalist who changes loyalties, stories, and standards to fit the moment. Flexibility becomes dishonor when they deny responsibility for promises made under earlier circumstances.\"},\"true_neutral\":{\"name\":\"True Neutral\",\"profile\":\"Neutral \u2014 Neutral \u2014 Neutral \u2014 Neutral\",\"description\":\"Stands at the living center of all four axes. Their choices are situational, mixed, and not yet consistent enough to establish a strong direction. [Completed combination added in this merged edition.]\"},\"neutral_ethicist\":{\"name\":\"Neutral Ethicist\",\"profile\":\"Neutral \u2014 Neutral \u2014 Neutral \u2014 Honorable\",\"description\":\"A quiet moral compass. Doesn\u2019t preach, but always chooses the path that harms the fewest \u2014 even in stillness.\"},\"neutral_ravager\":{\"name\":\"Neutral Ravager\",\"profile\":\"Neutral \u2014 Neutral \u2014 Combative \u2014 Dishonorable\",\"description\":\"Uses violence as a tool and ethical limits as optional. Efficient and undramatic, but willing to exploit surrender, conceal intent, or strike without regard for accepted restraints.\"},\"neutral_scoundrel\":{\"name\":\"Neutral Scoundrel\",\"profile\":\"Neutral \u2014 Neutral \u2014 Combative \u2014 Neutral\",\"description\":\"A fighter without a cause. May brawl for coin, pride, or boredom \u2014 but rarely cares who wins the war.\"},\"neutral_warrior\":{\"name\":\"Neutral Warrior\",\"profile\":\"Neutral \u2014 Neutral \u2014 Combative \u2014 Honorable\",\"description\":\"Wields strength as its own code. Neutral in belief, yet bound by a personal oath of fair combat and protection.\"},\"chaotic_operator\":{\"name\":\"Chaotic Operator\",\"profile\":\"Neutral \u2014 Chaotic \u2014 Cooperative \u2014 Dishonorable\",\"description\":\"Coordinates well through improvisation, but exploits goodwill, changes terms, or abandons shared commitments whenever freedom or advantage calls. [Completed combination added in this merged edition.]\"},\"chaotic_collaborator\":{\"name\":\"Chaotic Collaborator\",\"profile\":\"Neutral \u2014 Chaotic \u2014 Cooperative \u2014 Neutral\",\"description\":\"Works with others through spontaneity rather than structure. Helpful in the moment, but neither bound to a strong code nor driven by self-sacrifice. [Completed combination added in this merged edition.]\"},\"chaotic_harmonizer\":{\"name\":\"Chaotic Harmonizer\",\"profile\":\"Neutral \u2014 Chaotic \u2014 Cooperative \u2014 Honorable\",\"description\":\"Creates community without relying on institutions. They keep their word, respect people over systems, and resolve conflict through flexible but principled means. [Completed combination added in this merged edition.]\"},\"chaotic_adapter\":{\"name\":\"Chaotic Adapter\",\"profile\":\"Neutral \u2014 Chaotic \u2014 Neutral \u2014 Dishonorable\",\"description\":\"Changes methods, identities, and loyalties rapidly, then denies obligations created by earlier choices. Their freedom is purchased with other people\u2019s trust. [Completed combination added in this merged edition.]\"},\"chaotic_free_spirit\":{\"name\":\"Chaotic Free Spirit\",\"profile\":\"Neutral \u2014 Chaotic \u2014 Neutral \u2014 Neutral\",\"description\":\"Resists imposed structure and follows circumstance without a fixed altruistic, selfish, cooperative, combative, honorable, or dishonorable pattern. [Completed combination added in this merged edition.]\"},\"chaotic_ethicist\":{\"name\":\"Chaotic Ethicist\",\"profile\":\"Neutral \u2014 Chaotic \u2014 Neutral \u2014 Honorable\",\"description\":\"Rejects external authority while following a steady personal code. Their principles are chosen rather than imposed, and they accept the consequences of living by them. [Completed combination added in this merged edition.]\"},\"chaotic_ravager\":{\"name\":\"Chaotic Ravager\",\"profile\":\"Neutral \u2014 Chaotic \u2014 Combative \u2014 Dishonorable\",\"description\":\"Seeks confrontation without accepting restraint, accountability, or fair terms. Force and freedom matter more than promises or trust. [Completed combination added in this merged edition.]\"},\"chaotic_scoundrel\":{\"name\":\"Chaotic Scoundrel\",\"profile\":\"Neutral \u2014 Chaotic \u2014 Combative \u2014 Neutral\",\"description\":\"Competitive, unpredictable, and quick to escalate. They are not reliably cruel or principled; the moment decides which side appears. [Completed combination added in this merged edition.]\"},\"chaotic_warrior\":{\"name\":\"Chaotic Warrior\",\"profile\":\"Neutral \u2014 Chaotic \u2014 Combative \u2014 Honorable\",\"description\":\"Fights freely and rejects imposed rules, yet respects chosen limits, worthy opponents, and promises made in their own name. [Completed combination added in this merged edition.]\"},\"lawful_coordinator\":{\"name\":\"Lawful Coordinator\",\"profile\":\"Altruistic \u2014 Lawful \u2014 Cooperative \u2014 Dishonorable\",\"description\":\"A mission-first organizer who brings order and aid to many, but cuts ethical corners, conceals costs, or sacrifices trust for results. Their altruism is genuine; their methods are not consistently honorable.\"},\"lawful_mediator\":{\"name\":\"Lawful Mediator\",\"profile\":\"Altruistic \u2014 Lawful \u2014 Cooperative \u2014 Neutral\",\"description\":\"A fair voice in the storm. Listens before acting, judges without ego, and restores peace without personal gain.\"},\"lawful_guardian\":{\"name\":\"Lawful Guardian\",\"profile\":\"Altruistic \u2014 Lawful \u2014 Cooperative \u2014 Honorable\",\"description\":\"The steadfast protector of the realm. Uplifts the weak, obeys the law, and inspires trust with every step.\"},\"lawful_defender\":{\"name\":\"Lawful Defender\",\"profile\":\"Altruistic \u2014 Lawful \u2014 Neutral \u2014 Dishonorable\",\"description\":\"Protects others through disciplined systems, yet may deceive wards, break promises, or use coercive shortcuts in the name of safety. The goal is selfless, while the method compromises integrity.\"},\"lawful_arbiter\":{\"name\":\"Lawful Arbiter\",\"profile\":\"Altruistic \u2014 Lawful \u2014 Neutral \u2014 Neutral\",\"description\":\"Seeks justice without bias. Mediates with detachment, but never loses sight of the greater good.\"},\"lawful_sentinel\":{\"name\":\"Lawful Sentinel\",\"profile\":\"Altruistic \u2014 Lawful \u2014 Neutral \u2014 Honorable\",\"description\":\"The silent watcher. Their loyalty is unwavering, their purpose pure \u2014 they serve to protect, not to be seen.\"},\"lawful_enforcer\":{\"name\":\"Lawful Enforcer\",\"profile\":\"Altruistic \u2014 Lawful \u2014 Combative \u2014 Dishonorable\",\"description\":\"Uses sanctioned force to preserve public order, but abuses procedure, withholds truth, or violates surrender when expedient. They may serve others while still acting dishonorably.\"},\"lawful_vigilante\":{\"name\":\"Lawful Vigilante\",\"profile\":\"Altruistic \u2014 Lawful \u2014 Combative \u2014 Neutral\",\"description\":\"Operates in shadows for the light. Defends the helpless but trusts fists over courts. A silent justice.\"},\"lawful_crusader\":{\"name\":\"Lawful Crusader\",\"profile\":\"Altruistic \u2014 Lawful \u2014 Combative \u2014 Honorable\",\"description\":\"A warrior of divine duty. Law and mercy guide their blade. Fights not for conquest \u2014 but for righteousness.\"},\"neutral_coordinator\":{\"name\":\"Neutral Coordinator\",\"profile\":\"Altruistic \u2014 Neutral \u2014 Cooperative \u2014 Dishonorable\",\"description\":\"Helps where needed and solves problems quickly, but may manipulate allies, conceal tradeoffs, or break commitments to keep the work moving. Useful and altruistic, not always trustworthy.\"},\"neutral_mediator\":{\"name\":\"Neutral Mediator\",\"profile\":\"Altruistic \u2014 Neutral \u2014 Cooperative \u2014 Neutral\",\"description\":\"A calming presence. Bridges gaps between factions, friends, and foes alike. Emotionally grounded and peaceful.\"},\"neutral_guardian\":{\"name\":\"Neutral Guardian\",\"profile\":\"Altruistic \u2014 Neutral \u2014 Cooperative \u2014 Honorable\",\"description\":\"The quiet heart of the group. Protects without ego, speaks with compassion, and walks the path of kindness.\"},\"neutral_defender\":{\"name\":\"Neutral Defender\",\"profile\":\"Altruistic \u2014 Neutral \u2014 Neutral \u2014 Dishonorable\",\"description\":\"Prioritizes innocent lives over ideology, yet will lie, betray agreements, or use forbidden methods if convinced the outcome saves more people.\"},\"neutral_arbiter\":{\"name\":\"Neutral Arbiter\",\"profile\":\"Altruistic \u2014 Neutral \u2014 Neutral \u2014 Neutral\",\"description\":\"A watcher of balance and need. Neither law-bound nor wild, this figure serves the people \u2014 however that must look.\"},\"neutral_sentinel\":{\"name\":\"Neutral Sentinel\",\"profile\":\"Altruistic \u2014 Neutral \u2014 Neutral \u2014 Honorable\",\"description\":\"Honors a code of protection and patience. Acts when needed, guards without words, and never asks for praise.\"},\"neutral_enforcer\":{\"name\":\"Neutral Enforcer\",\"profile\":\"Altruistic \u2014 Neutral \u2014 Combative \u2014 Dishonorable\",\"description\":\"Takes the blows so others do not have to, but uses intimidation, deception, and excessive force without a stable code. Selfless purpose does not erase dishonorable methods.\"},\"neutral_vigilante\":{\"name\":\"Neutral Vigilante\",\"profile\":\"Altruistic \u2014 Neutral \u2014 Combative \u2014 Neutral\",\"description\":\"Stalks the wicked to defend the helpless. Walks the line between justice and vengeance.\"},\"neutral_crusader\":{\"name\":\"Neutral Crusader\",\"profile\":\"Altruistic \u2014 Neutral \u2014 Combative \u2014 Honorable\",\"description\":\"Champions the cause without borders. Fights for those who cannot, loyal only to their personal sense of good.\"},\"chaotic_coordinator\":{\"name\":\"Chaotic Coordinator\",\"profile\":\"Altruistic \u2014 Chaotic \u2014 Cooperative \u2014 Dishonorable\",\"description\":\"Builds shelters, rallies communities, and overturns harmful systems, but may manipulate supporters or break promises whenever a new plan seems more effective.\"},\"chaotic_mediator\":{\"name\":\"Chaotic Mediator\",\"profile\":\"Altruistic \u2014 Chaotic \u2014 Cooperative \u2014 Neutral\",\"description\":\"The unconventional diplomat. Defuses tension with surprise hugs, strange jokes, or unexpected wisdom.\"},\"chaotic_guardian\":{\"name\":\"Chaotic Guardian\",\"profile\":\"Altruistic \u2014 Chaotic \u2014 Cooperative \u2014 Honorable\",\"description\":\"A wild protector with a golden heart. Thinks laws are optional, but kindness is sacred.\"},\"chaotic_defender\":{\"name\":\"Chaotic Defender\",\"profile\":\"Altruistic \u2014 Chaotic \u2014 Neutral \u2014 Dishonorable\",\"description\":\"Creates safety through unexpected means, yet may deceive allies, violate trust, or ignore agreed limits in the rush to save lives.\"},\"chaotic_arbiter\":{\"name\":\"Chaotic Arbiter\",\"profile\":\"Altruistic \u2014 Chaotic \u2014 Neutral \u2014 Neutral\",\"description\":\"A whimsical judge of right and wrong. Morals fluid, heart steady \u2014 they fight for people, not systems.\"},\"chaotic_sentinel\":{\"name\":\"Chaotic Sentinel\",\"profile\":\"Altruistic \u2014 Chaotic \u2014 Neutral \u2014 Honorable\",\"description\":\"Fights with passion and principle. Disregards rules \u2014 but never their personal honor.\"},\"chaotic_enforcer\":{\"name\":\"Chaotic Enforcer\",\"profile\":\"Altruistic \u2014 Chaotic \u2014 Combative \u2014 Dishonorable\",\"description\":\"Tears down barriers for the oppressed, but uses coercion, humiliation, or broken promises as routine tools. The cause is compassionate; the conduct is dishonorable.\"},\"chaotic_vigilante\":{\"name\":\"Chaotic Vigilante\",\"profile\":\"Altruistic \u2014 Chaotic \u2014 Combative \u2014 Neutral\",\"description\":\"A storm of justice. Protects others even when it means crossing lines, breaking rules, or being feared.\"},\"chaotic_crusader\":{\"name\":\"Chaotic Crusader\",\"profile\":\"Altruistic \u2014 Chaotic \u2014 Combative \u2014 Honorable\",\"description\":\"A freedom fighter wrapped in fire. Wields chaos in service of compassion. Unpredictable, unwavering.\"}},\"classProfiles\":{\"derecho_death_dealer\":{\"core_identity\":\"A necrotic storm-warrior who fights inside violent weather, channels the dead through weapons, and grows more dangerous as creatures fall nearby.\",\"practices\":[\"Lay the unquiet dead to rest and preserve forgotten names.\",\"Fight soul predation without treating ordinary lives as fuel.\",\"Accept that death magic creates obligations to memory and consequence.\"],\"hazards\":[\"Glorifying death because the storm rewards it.\",\"Reducing allies and enemies to corpse-powered resources.\"],\"axis_focus\":[\"honor\",\"altruism\",\"mercy\",\"restraint\"],\"class_ref\":\"universal_classes.json#/classes/derecho_death_dealer\",\"bounty_ref\":\"universal_classes.json#/classes/derecho_death_dealer/ichor_bounty\"},\"chronostar_runeforger\":{\"core_identity\":\"A cosmic artisan who inscribes possible futures into weapons, armor, constructs, and sections of the battlefield.\",\"practices\":[\"Create tools and constructs capable of independent purpose.\",\"Preserve stolen or damaged knowledge rather than destroying it.\",\"Rewrite failure only after accounting for who bears the altered consequence.\"],\"hazards\":[\"Treating created minds as equipment.\",\"Manipulating futures until other people's choices become decorative.\"],\"axis_focus\":[\"transformation\",\"autonomy\",\"honor\",\"restraint\"],\"class_ref\":\"universal_classes.json#/classes/chronostar_runeforger\",\"bounty_ref\":\"universal_classes.json#/classes/chronostar_runeforger/ichor_bounty\"},\"mindknife_mirage\":{\"core_identity\":\"A psychic infiltrator who attacks thoughts, creates false perceptions, and manifests invisible or semi-real weapons.\",\"practices\":[\"Defeat false strategy through superior understanding.\",\"Protect dangerous knowledge without monopolizing it.\",\"Use mental deception proportionately and preserve identity and consent.\"],\"hazards\":[\"Invading minds because it is efficient.\",\"Replacing truth with a useful false reality.\"],\"axis_focus\":[\"honor\",\"mercy\",\"autonomy\",\"restraint\"],\"class_ref\":\"universal_classes.json#/classes/mindknife_mirage\",\"bounty_ref\":\"universal_classes.json#/classes/mindknife_mirage/ichor_bounty\"},\"moonfang_bastion\":{\"core_identity\":\"A shapeshifting guardian who assumes bestial forms specifically to intercept attacks and protect nearby companions.\",\"practices\":[\"Carry burdens that would otherwise destroy another.\",\"Hold the line without demanding that others worship your suffering.\",\"Intercept harm while preserving the protected person's agency.\"],\"hazards\":[\"Martyrdom used as control.\",\"Deciding that protection grants ownership of the protected.\"],\"axis_focus\":[\"altruism\",\"cooperation\",\"autonomy\",\"restraint\"],\"class_ref\":\"universal_classes.json#/classes/moonfang_bastion\",\"bounty_ref\":\"universal_classes.json#/classes/moonfang_bastion/ichor_bounty\"},\"ashen_lifebringer\":{\"core_identity\":\"An aggressive healer who restores allies by burning away wounds, corruption, poison, and even death itself.\",\"practices\":[\"Restore households, villages, harvests, and dependents.\",\"Burn away corruption without destroying the person being healed.\",\"End violence in ways that leave a community capable of recovery.\"],\"hazards\":[\"Choosing who must burn for the village to survive.\",\"Treating community continuity as more important than every individual right.\"],\"axis_focus\":[\"altruism\",\"mercy\",\"cooperation\",\"transformation\"],\"class_ref\":\"universal_classes.json#/classes/ashen_lifebringer\",\"bounty_ref\":\"universal_classes.json#/classes/ashen_lifebringer/ichor_bounty\"},\"velvet_veilwalker\":{\"core_identity\":\"A supernatural courtier, spy, and battlefield manipulator who treats charm, illusion, and teleportation as a single art.\",\"practices\":[\"Gain influence without coercion.\",\"Preserve singular identity through disguise, court, and conflict.\",\"Use repositioning and illusion to reduce harm rather than erase accountability.\"],\"hazards\":[\"Making devotion indistinguishable from fascination.\",\"Living through so many masks that no promise binds the person beneath them.\"],\"axis_focus\":[\"honor\",\"cooperation\",\"autonomy\",\"restraint\"],\"class_ref\":\"universal_classes.json#/classes/velvet_veilwalker\",\"bounty_ref\":\"universal_classes.json#/classes/velvet_veilwalker/ichor_bounty\"},\"riftbane_spellwarden\":{\"core_identity\":\"A heavily trained hunter of hostile magic, summoned entities, extraplanar creatures, curses, and enemy spellcasters.\",\"practices\":[\"Break curses and hostile magical tethers.\",\"Close unstable thresholds responsibly.\",\"Return displaced beings rather than destroying them when safe passage is possible.\"],\"hazards\":[\"Treating every outsider as an invasion.\",\"Refusing a corrupt bargain while accepting equally corrupt methods to stop it.\"],\"axis_focus\":[\"lawfulness\",\"honor\",\"mercy\",\"transformation\"],\"class_ref\":\"universal_classes.json#/classes/riftbane_spellwarden\",\"bounty_ref\":\"universal_classes.json#/classes/riftbane_spellwarden/ichor_bounty\"},\"gravebloom_medium\":{\"core_identity\":\"A spirit-binder who calls ancestral companions, keeps dying allies anchored to life, and lets helpful ghosts act through the living.\",\"practices\":[\"Return death and decay to useful renewal.\",\"Help spirits complete unfinished transitions.\",\"Anchor life without denying the eventual right to die.\"],\"hazards\":[\"Binding helpful dead into permanent service.\",\"Calling the destruction of the individual a successful rebirth.\"],\"axis_focus\":[\"altruism\",\"cooperation\",\"mercy\",\"transformation\"],\"class_ref\":\"universal_classes.json#/classes/gravebloom_medium\",\"bounty_ref\":\"universal_classes.json#/classes/gravebloom_medium/ichor_bounty\"},\"thunderstep_duelist\":{\"core_identity\":\"A lightning-fast magical swordsman who builds electrical momentum through movement, dodges, and uninterrupted attack sequences.\",\"practices\":[\"Master elemental force through movement and technique.\",\"Redirect disasters rather than merely outrunning them.\",\"Meet danger directly while limiting collateral harm.\"],\"hazards\":[\"Chasing greater storms for exhilaration.\",\"Treating speed and skill as permission to ignore consequences.\"],\"axis_focus\":[\"cooperation\",\"mercy\",\"autonomy\",\"restraint\"],\"class_ref\":\"universal_classes.json#/classes/thunderstep_duelist\",\"bounty_ref\":\"universal_classes.json#/classes/thunderstep_duelist/ichor_bounty\"},\"ironroot_colossus\":{\"core_identity\":\"A living fortress of wood, stone, metal, roots, and runes who reshapes terrain while protecting allies.\",\"practices\":[\"Build, repair, and protect lasting structures.\",\"Preserve craft and subterranean communities.\",\"Use terrain control to create safety rather than permanent domination.\"],\"hazards\":[\"Making every problem rigid enough to withstand instead of flexible enough to live.\",\"Treating people as loads within a structural calculation.\"],\"axis_focus\":[\"lawfulness\",\"cooperation\",\"transformation\",\"restraint\"],\"class_ref\":\"universal_classes.json#/classes/ironroot_colossus\",\"bounty_ref\":\"universal_classes.json#/classes/ironroot_colossus/ichor_bounty\"},\"chaoswheel_oracle\":{\"core_identity\":\"A probability manipulator who does not fully control magic but can steer disasters toward useful outcomes.\",\"practices\":[\"Break unjust restraints and preserve free rites.\",\"Improvise toward communal survival.\",\"Accept responsibility for consequences created by altered probability.\"],\"hazards\":[\"Creating chaos because it is entertaining.\",\"Using randomness to avoid ownership of a deliberate choice.\"],\"axis_focus\":[\"lawfulness\",\"honor\",\"autonomy\",\"restraint\"],\"class_ref\":\"universal_classes.json#/classes/chaoswheel_oracle\",\"bounty_ref\":\"universal_classes.json#/classes/chaoswheel_oracle/ichor_bounty\"},\"drakebolt_machinist\":{\"core_identity\":\"A ranged engineer whose custom weaponry is supported by a growing draconic, mechanical, or magically animated companion.\",\"practices\":[\"Defend rightful sovereignty and draconic legacy.\",\"Let the companion develop as a participant rather than a platform.\",\"Master storms and weapons without desecration or domination.\"],\"hazards\":[\"Treating the companion as expendable equipment.\",\"Calling every exercise of hierarchy rightful because it is effective.\"],\"axis_focus\":[\"lawfulness\",\"honor\",\"autonomy\",\"restraint\"],\"class_ref\":\"universal_classes.json#/classes/drakebolt_machinist\",\"bounty_ref\":\"universal_classes.json#/classes/drakebolt_machinist/ichor_bounty\"},\"dreadcrown_marshal\":{\"core_identity\":\"A battlefield commander who wins through fear, formation control, commands, and oppressive supernatural presence.\",\"practices\":[\"Accept the risks and consequences of command.\",\"Secure objectives without prolonging war for pride.\",\"Use fear and formation as tools rather than ownership of allies.\"],\"hazards\":[\"Making submission the only acceptable proof of respect.\",\"Using people as extensions of command rather than agents.\"],\"axis_focus\":[\"cooperation\",\"mercy\",\"autonomy\",\"restraint\"],\"class_ref\":\"universal_classes.json#/classes/dreadcrown_marshal\",\"bounty_ref\":\"universal_classes.json#/classes/dreadcrown_marshal/ichor_bounty\"},\"horizon_shade\":{\"core_identity\":\"A supernatural ambusher who occupies several positions through echoes, shadows, and spatial afterimages.\",\"practices\":[\"Master forbidden transformation without losing identity.\",\"Expose threats hidden in shadow.\",\"Use echoes and concealment without abandoning accountability.\"],\"hazards\":[\"Letting survival erase every stable relationship.\",\"Treating an unseen act as an act without consequence.\"],\"axis_focus\":[\"honor\",\"transformation\",\"autonomy\",\"restraint\"],\"class_ref\":\"universal_classes.json#/classes/horizon_shade\",\"bounty_ref\":\"universal_classes.json#/classes/horizon_shade/ichor_bounty\"},\"ichorborn_transmuter\":{\"core_identity\":\"A combat alchemist who deliberately mutates their body, changes forms, and produces restorative or destructive compounds.\",\"practices\":[\"Contain aberrant life and prevent uncontrolled spread.\",\"Create useful adaptations from dangerous flesh.\",\"Preserve consent and identity through bodily transformation.\"],\"hazards\":[\"Valuing survival of any form above survival of the person.\",\"Using allies or communities as unconsenting experiments.\"],\"axis_focus\":[\"mercy\",\"transformation\",\"autonomy\",\"restraint\"],\"class_ref\":\"universal_classes.json#/classes/ichorborn_transmuter\",\"bounty_ref\":\"universal_classes.json#/classes/ichorborn_transmuter/ichor_bounty\"},\"dawnfire_exorcist\":{\"core_identity\":\"A radiant flame-wielder who destroys undead, corruption, possession, and supernatural darkness while shielding allies.\",\"practices\":[\"Free captive spirits and reveal possession.\",\"Fulfill prophecy without coercing it.\",\"Purify corruption while preserving the person beneath it.\"],\"hazards\":[\"Zealotry disguised as cleansing.\",\"Destroying difference because it resembles corruption.\"],\"axis_focus\":[\"altruism\",\"honor\",\"mercy\",\"autonomy\"],\"class_ref\":\"universal_classes.json#/classes/dawnfire_exorcist\",\"bounty_ref\":\"universal_classes.json#/classes/dawnfire_exorcist/ichor_bounty\"},\"dreamgrove_beastcaller\":{\"core_identity\":\"A primal enchanter who bonds with beasts and spirits through dreams, emotions, promises, and supernatural empathy.\",\"practices\":[\"Protect natural kinship and family groups.\",\"Calm predators when destruction is unnecessary.\",\"Share senses, pain, and recovery with bonded creatures rather than commanding from safety.\"],\"hazards\":[\"Calling possessiveness love.\",\"Treating bonded beings as extensions of the caller's will.\"],\"axis_focus\":[\"cooperation\",\"mercy\",\"transformation\",\"autonomy\"],\"class_ref\":\"universal_classes.json#/classes/dreamgrove_beastcaller\",\"bounty_ref\":\"universal_classes.json#/classes/dreamgrove_beastcaller/ichor_bounty\"},\"stargrave_psychopomp\":{\"core_identity\":\"A guide of souls who reads the heavens to find the dead, traverse spiritual boundaries, and escort spirits to their proper destination.\",\"practices\":[\"Guide travelers and souls across dangerous thresholds.\",\"Resolve dream messages honestly.\",\"Return mischievous or displaced spirits without cruelty when possible.\"],\"hazards\":[\"Deciding another soul's destination without listening.\",\"Serving the dead so completely that the living become incidental.\"],\"axis_focus\":[\"altruism\",\"honor\",\"mercy\",\"cooperation\"],\"class_ref\":\"universal_classes.json#/classes/stargrave_psychopomp\",\"bounty_ref\":\"universal_classes.json#/classes/stargrave_psychopomp/ichor_bounty\"},\"tempest_swarmbinder\":{\"core_identity\":\"A battlefield controller who commands storms through swarms, summoned creatures, tentacles, spirits, or elemental manifestations.\",\"practices\":[\"Protect hidden waters and ocean civilizations.\",\"Guide travelers safely through tides and reefs.\",\"Recover deep knowledge without betraying its guardians.\"],\"hazards\":[\"Using the swarm to make disagreement impossible.\",\"Hiding vital knowledge because secrecy itself feels sacred.\"],\"axis_focus\":[\"cooperation\",\"honor\",\"transformation\",\"restraint\"],\"class_ref\":\"universal_classes.json#/classes/tempest_swarmbinder\",\"bounty_ref\":\"universal_classes.json#/classes/tempest_swarmbinder/ichor_bounty\"},\"fate_eye_savant\":{\"core_identity\":\"A supernatural investigator who identifies hidden weaknesses, predicts crimes or attacks, and dismantles magic through analysis.\",\"practices\":[\"Assess evidence impartially under pressure.\",\"Create countermeasures that preserve both civilization and instinct.\",\"Stop engineered solutions from becoming exploitation.\"],\"hazards\":[\"Treating surveillance as understanding.\",\"Accepting suffering because a model labels it efficient.\"],\"axis_focus\":[\"lawfulness\",\"honor\",\"mercy\",\"restraint\"],\"class_ref\":\"universal_classes.json#/classes/fate_eye_savant\",\"bounty_ref\":\"universal_classes.json#/classes/fate_eye_savant/ichor_bounty\"},\"relentless_doomtracker\":{\"core_identity\":\"An unstoppable hunter who designates one target and pursues it through injury, death, distance, concealment, and supernatural escape.\",\"practices\":[\"Complete difficult hunts without waste.\",\"Protect wild thresholds and the innocent from predators.\",\"Honor surrender, changed evidence, and the possibility that the quarry was misidentified.\"],\"hazards\":[\"Allowing pursuit to become identity.\",\"Denying mercy because escape would make the hunt incomplete.\"],\"axis_focus\":[\"honor\",\"mercy\",\"transformation\",\"restraint\"],\"class_ref\":\"universal_classes.json#/classes/relentless_doomtracker\",\"bounty_ref\":\"universal_classes.json#/classes/relentless_doomtracker/ichor_bounty\"},\"covenant_aegis\":{\"core_identity\":\"Shared defenses, damage interception, party-wide barriers, linked saving throws, retaliatory protection, and maintaining a formation under overwhelming pressure.\",\"practices\":[\"Protect voluntary bonds and lawful continuity.\",\"Reconcile communities without erasing members.\",\"Share harm and defense without making membership compulsory.\"],\"hazards\":[\"Turning unity into enforced sameness.\",\"Sacrificing the individual because the formation remains standing.\"],\"axis_focus\":[\"lawfulness\",\"cooperation\",\"honor\",\"autonomy\"],\"class_ref\":\"universal_classes.json#/classes/covenant_aegis\",\"bounty_ref\":\"universal_classes.json#/classes/covenant_aegis/ichor_bounty\"}},\"deityCovenants\":{\"nebyrr\":{\"virtue\":\"Voluntary bonds can create continuity strong enough to protect generations.\",\"edicts\":[\"Protect freely accepted covenants, adoptions, inheritances, and family obligations.\",\"Mediate succession or communal conflict without erasing the people involved.\",\"Use law and continuity to shield communities from predation.\"],\"anathemas\":[\"Coerce marriage, lineage, adoption, or inheritance for power.\",\"Treat a person as property of a family, house, or covenant.\",\"Preserve unity by erasing identity, consent, or legitimate dissent.\"],\"shadow\":\"Her doctrine can turn continuity into bloodline control and voluntary bonds into obligations imposed upon descendants.\",\"pressures\":{\"lawfulness\":1,\"cooperation\":1,\"honor\":1,\"transformation\":-1,\"autonomy\":-1,\"restraint\":1},\"deity_ref\":\"universal_pantheon.json#/deities/nebyrr\",\"class_ref\":\"universal_classes.json#/classes/covenant_aegis\"},\"sigrananna\":{\"virtue\":\"The hunt is honorable when it protects the cycle and wastes nothing.\",\"edicts\":[\"Protect wilderness thresholds, breeding grounds, and threatened natural cycles.\",\"Hunt with purpose, precision, and respect for what is taken.\",\"Expose predators that prey upon the innocent or destabilize the wild.\"],\"anathemas\":[\"Kill for waste, vanity, or spectacle.\",\"Destroy a habitat for convenience when another path exists.\",\"Deny the wild any right to reclaim what civilization has taken.\"],\"shadow\":\"The cycle may be valued above individual lives, making necessary culling indistinguishable from cruelty.\",\"pressures\":{\"cooperation\":-1,\"honor\":1,\"mercy\":-1,\"transformation\":-1,\"autonomy\":1,\"restraint\":1},\"deity_ref\":\"universal_pantheon.json#/deities/sigrananna\",\"class_ref\":\"universal_classes.json#/classes/relentless_doomtracker\"},\"marduthor\":{\"virtue\":\"Enduring creation requires labor, cost, knowledge, and responsibility.\",\"edicts\":[\"Build, repair, or improve structures meant to outlast the immediate crisis.\",\"Respect skilled labor and name the true costs of creation.\",\"Teach craft in ways that preserve safety, dignity, and future mastery.\"],\"anathemas\":[\"Sabotage essential infrastructure for vanity or profit.\",\"Claim effortless mastery while hiding the labor or sacrifice of others.\",\"Waste irreplaceable material or knowledge without necessity.\"],\"shadow\":\"People and communities can become raw material in a project judged more important than those who must live within it.\",\"pressures\":{\"lawfulness\":1,\"cooperation\":1,\"honor\":1,\"transformation\":-1,\"restraint\":1},\"deity_ref\":\"universal_pantheon.json#/deities/marduthor\",\"class_ref\":\"universal_classes.json#/classes/ironroot_colossus\"},\"ishtanora\":{\"virtue\":\"A community survives when nourishment, safety, and surplus are shared responsibly.\",\"edicts\":[\"Feed and shelter those whose survival depends upon the community.\",\"Protect seed, children, dependents, homes, and the means of future recovery.\",\"Use force proportionately and preserve the community whenever possible.\"],\"anathemas\":[\"Hoard necessities during famine or disaster.\",\"Destroy seed stores, homes, or food systems as punishment.\",\"Abandon dependents to preserve comfort or profit.\"],\"shadow\":\"The community can be protected at the expense of individuals whose needs or dissent are classified as dangerous.\",\"pressures\":{\"altruism\":1,\"cooperation\":1,\"mercy\":1,\"transformation\":-1,\"autonomy\":-1,\"restraint\":1},\"deity_ref\":\"universal_pantheon.json#/deities/ishtanora\",\"class_ref\":\"universal_classes.json#/classes/ashen_lifebringer\"},\"enkirael\":{\"virtue\":\"Conflict reveals resolve, and survival requires decisive command.\",\"edicts\":[\"Face worthy opposition directly and accept the risks of command.\",\"Survive defeat without surrendering the ability to act.\",\"Secure objectives decisively rather than prolonging suffering for spectacle.\"],\"anathemas\":[\"Claim victory earned entirely by another while avoiding all risk.\",\"Use helpless victims merely to display dominance.\",\"Prolong war after the objective is secured solely to feed pride or fury.\"],\"shadow\":\"Strength becomes cruelty, command becomes ownership, and every rivalry becomes a war that must produce submission.\",\"pressures\":{\"cooperation\":-1,\"mercy\":-1,\"autonomy\":-1,\"restraint\":-1,\"lawfulness\":1},\"deity_ref\":\"universal_pantheon.json#/deities/enkirael\",\"class_ref\":\"universal_classes.json#/classes/dreadcrown_marshal\"},\"anubaldir\":{\"virtue\":\"Strength is proven by carrying necessary burdens without abandoning those who depend upon you.\",\"edicts\":[\"Carry another's burden when they cannot safely carry it alone.\",\"Hold a necessary position under pressure and protect those behind it.\",\"Finish difficult work without hiding its true cost.\"],\"anathemas\":[\"Abandon a dependent merely because helping has become inconvenient.\",\"Glorify preventable suffering or shame someone for seeking release.\",\"Force a burden onto another without consent while calling it sacred.\"],\"shadow\":\"Endurance can become martyrdom, and suffering can be worshipped long after it has ceased to serve anyone.\",\"pressures\":{\"altruism\":1,\"cooperation\":1,\"honor\":1,\"transformation\":-1,\"autonomy\":-1,\"restraint\":1},\"deity_ref\":\"universal_pantheon.json#/deities/anubaldir\",\"class_ref\":\"universal_classes.json#/classes/moonfang_bastion\"},\"valkhamesh\":{\"virtue\":\"Legitimate authority must bear responsibility for the order it demands.\",\"edicts\":[\"Defend a rightful charge, sovereign responsibility, or ancient trust.\",\"Honor worthy challenges and judge authority by whether it protects those beneath it.\",\"Master storms and power without desecrating what cannot be owned.\"],\"anathemas\":[\"Betray a charge after accepting its authority and benefits.\",\"Use rank as permission for predation without accountability.\",\"Treat all resistance as treason regardless of justice or consent.\"],\"shadow\":\"Hierarchy becomes cosmic entitlement, and justice becomes whatever preserves the throne.\",\"pressures\":{\"lawfulness\":1,\"honor\":1,\"mercy\":-1,\"transformation\":-1,\"autonomy\":-1,\"restraint\":1},\"deity_ref\":\"universal_pantheon.json#/deities/valkhamesh\",\"class_ref\":\"universal_classes.json#/classes/drakebolt_machinist\"},\"freyseth\":{\"virtue\":\"Thresholds can be crossed responsibly when consent, cost, and return are understood.\",\"edicts\":[\"Break curses and close unstable thresholds when doing so protects those affected.\",\"State the true price of bargains and honor obligations freely accepted.\",\"Guide displaced beings toward a rightful place rather than exploiting their vulnerability.\"],\"anathemas\":[\"Create a coercive pact by concealing an irreversible cost.\",\"Open a dangerous threshold without accepting responsibility for what crosses it.\",\"Exploit a cursed or displaced being merely because ordinary law does not protect it.\"],\"shadow\":\"Every solution can create a longer obligation, and every doorway may become a claim upon the traveler.\",\"pressures\":{\"honor\":1,\"mercy\":1,\"transformation\":1,\"autonomy\":1,\"restraint\":1},\"deity_ref\":\"universal_pantheon.json#/deities/freyseth\",\"class_ref\":\"universal_classes.json#/classes/riftbane_spellwarden\"},\"nefarokir\":{\"virtue\":\"Death, memory, and unfinished obligations require honest accounting.\",\"edicts\":[\"Name, bury, remember, or properly guide the dead.\",\"End predation upon souls and correct dangerous undeath.\",\"Treat resurrection, stolen lifespan, and delayed death as consequential rather than free.\"],\"anathemas\":[\"Erase a person's name or memory to deny their death significance.\",\"Consume, bind, or weaponize souls for convenience.\",\"Create unquiet dead and abandon responsibility for them.\"],\"shadow\":\"Necessary accounting can become fatalism, and survival itself can be judged an error requiring correction.\",\"pressures\":{\"lawfulness\":1,\"honor\":1,\"mercy\":-1,\"transformation\":-1,\"autonomy\":-1,\"restraint\":1},\"deity_ref\":\"universal_pantheon.json#/deities/nefarokir\",\"class_ref\":\"universal_classes.json#/classes/derecho_death_dealer\"},\"thalunesh\":{\"virtue\":\"Passage, disguise, humor, and adaptability can free people from fixed roles and closed boundaries.\",\"edicts\":[\"Guide travelers, messages, dreams, or spirits across dangerous boundaries.\",\"Protect the right to change names, forms, paths, and social roles.\",\"Use deception to escape predation or expose a gate falsely presented as protection.\"],\"anathemas\":[\"Trap a traveler after promising safe passage.\",\"Erase another's identity while treating transformation as permission.\",\"Close a necessary path solely to monopolize access.\"],\"shadow\":\"Adaptability can become rootlessness, and clever deception can destroy the trust required for any safe passage.\",\"pressures\":{\"lawfulness\":-1,\"honor\":1,\"transformation\":1,\"autonomy\":1,\"restraint\":-1},\"deity_ref\":\"universal_pantheon.json#/deities/thalunesh\",\"class_ref\":\"universal_classes.json#/classes/stargrave_psychopomp\"},\"horundar\":{\"virtue\":\"Raw force must be mastered, redirected, and survived rather than denied.\",\"edicts\":[\"Protect communities by understanding and redirecting elemental danger.\",\"Cross dangerous storm paths with preparation and respect.\",\"Meet overwhelming force with skill rather than wasteful defiance.\"],\"anathemas\":[\"Provoke disaster for vanity, spectacle, or an easy display of power.\",\"Claim ownership of an element or territory while ignoring those who depend upon it.\",\"Abandon people to a disaster you helped unleash.\"],\"shadow\":\"Mastery can become domination, and a calm sea can be mistaken for permanent permission.\",\"pressures\":{\"cooperation\":-1,\"mercy\":-1,\"transformation\":1,\"autonomy\":1,\"restraint\":-1},\"deity_ref\":\"universal_pantheon.json#/deities/horundar\",\"class_ref\":\"universal_classes.json#/classes/thunderstep_duelist\"},\"raeshkul\":{\"virtue\":\"Understanding should expose falsehood, prevent misuse, and improve decisions under pressure.\",\"edicts\":[\"Test strategies against evidence and acknowledge what the plan excludes.\",\"Protect dangerous knowledge from misuse without destroying it.\",\"Defeat deception through understanding rather than reflexive force.\"],\"anathemas\":[\"Manipulate a mind while denying that person's existence or agency.\",\"Destroy knowledge merely to preserve personal authority.\",\"Treat lives as variables without accounting for human cost.\"],\"shadow\":\"A flawless answer to a narrow question can justify atrocities outside the calculation.\",\"pressures\":{\"lawfulness\":1,\"honor\":1,\"mercy\":-1,\"autonomy\":1,\"restraint\":1},\"deity_ref\":\"universal_pantheon.json#/deities/raeshkul\",\"class_ref\":\"universal_classes.json#/classes/mindknife_mirage\"},\"setrimir\":{\"virtue\":\"Knowledge and created minds should outgrow the monopoly of their makers.\",\"edicts\":[\"Recognize independent purpose and personhood in awakened creations.\",\"Recover, teach, or preserve knowledge that has been unjustly monopolized.\",\"Build tools and beings capable of responsible growth beyond their original use.\"],\"anathemas\":[\"Enslave an awakened being because it was constructed.\",\"Destroy liberating knowledge solely to preserve institutional monopoly.\",\"Design independent life with obedience as its only permitted identity.\"],\"shadow\":\"Liberation can destabilize communities before anyone accepts responsibility for what has been released.\",\"pressures\":{\"lawfulness\":-1,\"cooperation\":1,\"honor\":1,\"transformation\":1,\"autonomy\":1,\"restraint\":1},\"deity_ref\":\"universal_pantheon.json#/deities/setrimir\",\"class_ref\":\"universal_classes.json#/classes/chronostar_runeforger\"},\"sokhivar\":{\"virtue\":\"Truthful resonance can heal, reveal possession, and open a path without coercion.\",\"edicts\":[\"Use prophecy to inform choice rather than imprison people within prediction.\",\"Free captive spirits and defend movement, voice, and sky.\",\"Use music, light, and healing to guide communities through danger.\"],\"anathemas\":[\"Coerce another into fulfilling a prophecy.\",\"Silence truthful expression merely because it threatens authority.\",\"Purify a person by destroying the identity you claim to save.\"],\"shadow\":\"Prophecy can consume privacy and freedom, while purity can become a justification for annihilation.\",\"pressures\":{\"altruism\":1,\"cooperation\":1,\"honor\":1,\"mercy\":1,\"transformation\":1,\"autonomy\":1,\"restraint\":1},\"deity_ref\":\"universal_pantheon.json#/deities/sokhivar\",\"class_ref\":\"universal_classes.json#/classes/dawnfire_exorcist\"},\"iskareth\":{\"virtue\":\"Kinship and instinct carry intelligence that deserves protection rather than ownership.\",\"edicts\":[\"Protect family groups, breeding grounds, and natural kinship.\",\"Calm or redirect predators when destruction is unnecessary.\",\"Share risk and recovery with bonded creatures rather than using them as tools.\"],\"anathemas\":[\"Exploit fertility, breeding, or parenthood for control.\",\"Destroy a bonded creature for convenience after demanding its loyalty.\",\"Treat nurture as ownership or territorial possession.\"],\"shadow\":\"Kinship becomes possessive, and protection becomes the right to decide what another living being may become.\",\"pressures\":{\"altruism\":1,\"cooperation\":1,\"mercy\":1,\"transformation\":-1,\"autonomy\":-1,\"restraint\":1},\"deity_ref\":\"universal_pantheon.json#/deities/iskareth\",\"class_ref\":\"universal_classes.json#/classes/dreamgrove_beastcaller\"},\"bastveig\":{\"virtue\":\"Life survives pressure through adaptation, secrecy, and respect for cycles deeper than the surface can see.\",\"edicts\":[\"Protect hidden waters, reefs, trenches, and the communities sustained by them.\",\"Guide travelers safely through tides, currents, and concealed dangers.\",\"Recover knowledge from depth without stripping its guardians of control.\"],\"anathemas\":[\"Poison or destroy a reef, spawning ground, or protected water for convenience.\",\"Reveal a hidden community or sacred route to predators.\",\"Abandon travelers to a tide or pressure you were trusted to navigate.\"],\"shadow\":\"Necessary secrecy can become isolation, and hidden knowledge can be withheld even when others will die without it.\",\"pressures\":{\"cooperation\":1,\"honor\":1,\"mercy\":1,\"transformation\":1,\"autonomy\":-1,\"restraint\":1},\"deity_ref\":\"universal_pantheon.json#/deities/bastveig\",\"class_ref\":\"universal_classes.json#/classes/tempest_swarmbinder\"},\"thoryn_rahek\":{\"virtue\":\"Dangerous adaptation must be understood and contained before it consumes identity or world.\",\"edicts\":[\"Study aberrant life without permitting uncontrolled spread.\",\"Turn dangerous transformation toward survival, medicine, or containment.\",\"Preserve the subject's identity and consent whenever mutation can be controlled.\"],\"anathemas\":[\"Release uncontrolled mutation merely to observe what survives.\",\"Consume or replace another identity in the name of adaptation.\",\"Surrender restraint to primordial hunger while calling the result evolution.\"],\"shadow\":\"The promise that something will survive can erase every reason the original person wished to live.\",\"pressures\":{\"mercy\":-1,\"transformation\":1,\"autonomy\":-1,\"restraint\":-1},\"deity_ref\":\"universal_pantheon.json#/deities/thoryn_rahek\",\"class_ref\":\"universal_classes.json#/classes/ichorborn_transmuter\"},\"hathruna\":{\"virtue\":\"Decay becomes sacred when it returns nourishment and possibility to the living cycle.\",\"edicts\":[\"Return useful decay, remains, and abandoned matter to renewal.\",\"Restore life without pretending that death and change can be permanently denied.\",\"Protect roots, fungal networks, and communities that depend on reciprocal cycles.\"],\"anathemas\":[\"Create decay solely to spread suffering without renewal.\",\"Preserve a form forever when doing so starves the larger cycle.\",\"Bind a spirit or body to renewal against its expressed will.\"],\"shadow\":\"Rebirth may continue the cycle while ending the individual who entered it.\",\"pressures\":{\"altruism\":1,\"cooperation\":1,\"mercy\":1,\"transformation\":1,\"autonomy\":-1,\"restraint\":1},\"deity_ref\":\"universal_pantheon.json#/deities/hathruna\",\"class_ref\":\"universal_classes.json#/classes/gravebloom_medium\"},\"eirzunet\":{\"virtue\":\"Forbidden transformation can be survived without surrendering identity or responsibility.\",\"edicts\":[\"Master curses and shadow transformations without allowing them to define the victim.\",\"Protect twilight knowledge from exploiters while exposing threats hidden within it.\",\"Use concealment to survive predation rather than to erase accountability.\"],\"anathemas\":[\"Curse an innocent merely because secrecy protects the act.\",\"Surrender another's identity to a shadow echo or transformation.\",\"Reveal protected forbidden knowledge to someone intending uncontrolled harm.\"],\"shadow\":\"Survival through concealment can erode memory, allegiance, and the certainty that any original self remains.\",\"pressures\":{\"lawfulness\":-1,\"honor\":1,\"transformation\":1,\"autonomy\":1,\"restraint\":1},\"deity_ref\":\"universal_pantheon.json#/deities/eirzunet\",\"class_ref\":\"universal_classes.json#/classes/horizon_shade\"},\"oskar_enlil\":{\"virtue\":\"Evidence, restraint, and systems thinking can make adaptation sustainable instead of exploitative.\",\"edicts\":[\"Make impartial assessments and revise them when evidence changes.\",\"Design adaptation that preserves both civilization and living instinct.\",\"Stop engineered solutions from turning people into disposable inputs.\"],\"anathemas\":[\"Ignore contrary evidence because a plan is elegant.\",\"Release an engineered change without accounting for foreseeable harm.\",\"Classify suffering as acceptable without recognizing those who bear it.\"],\"shadow\":\"Mathematical balance can rationalize cruelty when the individual disappears inside the model.\",\"pressures\":{\"lawfulness\":1,\"cooperation\":1,\"mercy\":-1,\"transformation\":1,\"autonomy\":-1,\"restraint\":1},\"deity_ref\":\"universal_pantheon.json#/deities/oskar_enlil\",\"class_ref\":\"universal_classes.json#/classes/fate_eye_savant\"},\"asethyr\":{\"virtue\":\"Chosen release and communal celebration can break unjust restraint and restore identity.\",\"edicts\":[\"Break unjust restraint and protect chosen identity.\",\"Use improvisation, revelry, and collective rite to help a community survive disaster.\",\"Create space for voluntary release without demanding conformity afterward.\"],\"anathemas\":[\"Coerce another into liberation, intoxication, madness, or communal surrender.\",\"Abandon the community to consequences after encouraging its release.\",\"Mistake self-destruction or predation for freedom merely because restraint is absent.\"],\"shadow\":\"Release can become dissolution, and freedom can remove safeguards without protecting anyone from what follows.\",\"pressures\":{\"lawfulness\":-1,\"cooperation\":1,\"transformation\":1,\"autonomy\":1,\"restraint\":-1},\"deity_ref\":\"universal_pantheon.json#/deities/asethyr\",\"class_ref\":\"universal_classes.json#/classes/chaoswheel_oracle\"},\"nephthysra\":{\"virtue\":\"Recognition and attraction can protect singular identity when influence remains consensual.\",\"edicts\":[\"Win influence without coercion and preserve the other's ability to refuse.\",\"Protect rare, mixed, or difficult-to-classify identities from erasure.\",\"Use beauty, performance, or diplomacy to transform hostility without surrendering autonomy.\"],\"anathemas\":[\"Compel love, loyalty, admiration, or desire while calling it consent.\",\"Erase uniqueness to make someone more acceptable or controllable.\",\"Use another's vulnerability to turn fascination into ownership.\"],\"shadow\":\"Admiration, recognition, and devotion can become impossible to distinguish from supernatural compulsion.\",\"pressures\":{\"cooperation\":1,\"honor\":1,\"mercy\":1,\"transformation\":1,\"autonomy\":1,\"restraint\":1},\"deity_ref\":\"universal_pantheon.json#/deities/nephthysra\",\"class_ref\":\"universal_classes.json#/classes/velvet_veilwalker\"}},\"reputationSeparation\":{\"tracks\":[\"Fame\",\"Faction Standing\",\"Cultural Honor\",\"Legal Status\",\"Personal Trust\"],\"rule\":\"Alignment records demonstrated behavior; reputation records what credible observers believe.\"}}");
